def s1(u):
    G, H, I, J, K, L, M, N, O, P = u[6:16]
    return round(G * .18 + H * .15 + I * .12 + J * .08 + K * .13 + L * .10 + M * .12 + N * .12 - O * .07 + P * .10, 2)


def s2(u):
    G, H, I, J, K, L, M, N, O, P = u[6:16]
    return round(I * .16 + J * .20 + K * .12 + L * .10 + (6 - M) * .08 + (6 - N) * .08 + O * .06 + P * .14 + G * .06, 2)


def rec(u):
    G, H, I, J, K, L, M, N, O, P = u[6:16]
    if (G >= 4 and H >= 4 and K >= 3 and P >= 4) or s1(u) >= 3.7:
        return "Первый"
    if s2(u) >= 3.6:
        return "Следующий"
    return "Не включать"


